import { HttpErrorResponse } from '@angular/common/http';
import { inject, Injectable } from '@angular/core';
import { BehaviorSubject, EMPTY, Observable } from 'rxjs';
import { catchError, tap } from 'rxjs/operators';
import { DataApiService } from '../../../services/data-api.service';
import { MensajesHttpService } from '../../../utils/mensajesHttp/mensajes-http.service';
import { DataApi } from '../../../Model/dataApi';

@Injectable({
  providedIn: 'root',
})
export class EntregasFacadeService {

  private dataApi = inject(DataApiService);
  private _mensajesHttp = inject(MensajesHttpService);

  private Cargando$ = new BehaviorSubject<boolean>(false);
  public responseCargando$: Observable<boolean> = this.Cargando$.asObservable();

  private EntregasConsigna$ = new BehaviorSubject<any>(null);
  public responseEntregasConsignas$: Observable<any[]> = this.EntregasConsigna$.asObservable();

  private seg(valor: any, centinela: any = 0): string {
    if (valor === null || valor === undefined || valor === '') { return String(centinela); }
    return encodeURIComponent(String(valor));
  }

  MostrarEntregasConsigna(f: { idRevendedora: any, busqueda: any, pagina: number, tamanoPagina: number }) {
    this.Cargando$.next(true);
    this.EntregasConsigna$.next([]);
    const params =
      `${this.seg(f.idRevendedora)}/` +
      `${this.seg(f.busqueda, 'null')}/` +
      `${this.seg(f.pagina, 1)}/` +
      `${this.seg(f.tamanoPagina, 100)}`;

    const request$ = this.dataApi.GetDataApi(`inventario/v1/consignacion/entregas/`, params).pipe(
      tap((result: DataApi | any) => {
        this.EntregasConsigna$.next(result?.data.Table0);
        this.Cargando$.next(false);
      }),
      catchError((error: HttpErrorResponse) => {
        this.EntregasConsigna$.next([]);
        this.Cargando$.next(false);
        this._mensajesHttp.mostrarErrorHttp(error, 'Ocurrio un error al mostar las entregas en consigna', '');
        return EMPTY;
      })
    );

    return request$.subscribe();
  }

  EntregasConsigna(params: any, respuesta) {
    this.Cargando$.next(true);
    const request$ = this.dataApi.PostDataApi(`inventario/v1/entrada-consigna/`, params).pipe(
      tap((result: DataApi | any) => {
        respuesta(result);
        this.Cargando$.next(false);
      }),
      catchError((error: HttpErrorResponse) => {
        respuesta(null);
        this.Cargando$.next(false);
        this._mensajesHttp.mostrarErrorHttp(error, 'Ocurrio un error al realizar la entrega en consigna', '');
        return EMPTY;
      })
    );

    return request$.subscribe();
  }
}
