import { HttpErrorResponse } from '@angular/common/http';
import { inject, Injectable } from '@angular/core';
import { BehaviorSubject, EMPTY, from, Observable } from 'rxjs';
import { catchError, concatMap, tap, toArray } from 'rxjs/operators';
import { DataApiService } from '../../../services/data-api.service';
import { MensajesHttpService } from '../../../utils/mensajesHttp/mensajes-http.service';
import { DataApi } from '../../../Model/dataApi';

@Injectable({
  providedIn: 'root',
})
export class LiquidacionesFacadeService {

  private dataApi = inject(DataApiService);
  private _mensajesHttp = inject(MensajesHttpService);

  private Cargando$ = new BehaviorSubject<boolean>(false);
  public responseCargando$: Observable<boolean> = this.Cargando$.asObservable();

  private Liquidaciones$ = new BehaviorSubject<any>(null);
  public responseLiquidaciones$: Observable<any[]> = this.Liquidaciones$.asObservable();

  private Detalle$ = new BehaviorSubject<any>(null);
  public responseDetalle$: Observable<any[]> = this.Detalle$.asObservable();

  private ProductosConsigna$ = new BehaviorSubject<any>(null);
  public responseProductosConsigna$: Observable<any[]> = this.ProductosConsigna$.asObservable();

  private seg(valor: any, centinela: any = 0): string {
    if (valor === null || valor === undefined || valor === '') { return String(centinela); }
    return encodeURIComponent(String(valor));
  }

  MostrarLiquidaciones(f: { idRevendedora: any, estado: any, pagina: number, tamanoPagina: number }) {
    const url =
      `inventario/v1/liquidaciones/` +
      `${this.seg(f.idRevendedora)}/` +
      `${this.seg(f.estado, 'null')}/` +
      `${this.seg(f.pagina, 1)}/` +
      `${this.seg(f.tamanoPagina, 100)}`;

    this.Cargando$.next(true);
    this.Liquidaciones$.next([]);
    const request$ = this.dataApi.GetDataApi(url, '').pipe(
      tap((result: any) => {
        this.Cargando$.next(false);
        this.Liquidaciones$.next(result.data.Table0);
      }),
      catchError((error: HttpErrorResponse) => {
        this.Cargando$.next(false);
        this.Liquidaciones$.next([]);
        this._mensajesHttp.mostrarErrorHttp(error, 'Ocurrio un error al mostrar las liquidaciones', '');
        return EMPTY;
      })
    );
    return request$.subscribe();
  }


  MostrarDetalle(idLiquidacion: number) {
    const url = `inventario/v1/liquidaciones/${this.seg(idLiquidacion)}`;

    const request$ = this.dataApi.GetDataApi(url, '').pipe(
      tap((result: any) => {
        this.Detalle$.next(result.data.Table0);
      }),
      catchError((error: HttpErrorResponse) => {
        this.Detalle$.next([]);
        this._mensajesHttp.mostrarErrorHttp(error, 'Ocurrio un error al mostrar el detalle', '');
        return EMPTY;
      })
    );
    return request$.subscribe();
  }

  RegistrarLiquidacion(
    datos: { idRevendedora: any, idAlmacenRevendedora: any, usuario: any },
    lineas: any[],
    respuesta: (ok: boolean) => void
  ) {
    this.Cargando$.next(true);

    let idLiquidacion: any = null;

    const request$ = from(lineas).pipe(
      concatMap((linea: any) => {
        // objeto PLANO, tal como lo espera tu controller LiquidacionConsigna
        const params = {
          idRevendedora: datos.idRevendedora,
          idAlmacenRevendedora: datos.idAlmacenRevendedora,
          idProducto: linea.idProducto,
          cantidadVendida: linea.cantidadVendida,
          precioConsigna: linea.precioConsigna,
          precioVentaPublico: linea.precioVentaPublico ?? null,
          idLiquidacion: idLiquidacion,          // null en la 1ra; el id en las siguientes
          usuario: datos.usuario
        };

        return this.dataApi.PostDataApi(`inventario/v1/liquidacion-consigna/`, params).pipe(
          tap((result: any) => {
            const fila = result?.data?.Table0?.[0];
            if (fila && fila.id_liquidacion) {
              idLiquidacion = fila.id_liquidacion;
            }
          })
        );
      }),
      toArray(),
      tap(() => {
        this.Cargando$.next(false);
        respuesta(true);
      }),
      catchError((error: HttpErrorResponse) => {
        this.Cargando$.next(false);
        this._mensajesHttp.mostrarErrorHttp(error, 'Ocurrio un error al registrar la liquidacion', '');
        respuesta(false);
        return EMPTY;
      })
    );

    return request$.subscribe();
  }

  MostrarProductosConsigna(idAlmacen: number, busqueda: string) {
    const url =
      `inventario/v1/productos/consigna/` +
      `${this.seg(idAlmacen)}/` +
      `${this.seg(busqueda, 'null')}`;

    const request$ = this.dataApi.GetDataApi(url, '').pipe(
      tap((result: any) => {
        this.ProductosConsigna$.next(result.data.Table0);
      }),
      catchError((error: HttpErrorResponse) => {
        this.ProductosConsigna$.next([]);
        this._mensajesHttp.mostrarErrorHttp(error, 'Ocurrio un error al mostrar los productos en consigna', '');
        return EMPTY;
      })
    );
    return request$.subscribe();
  }
}
