import { inject, Injectable } from '@angular/core';
import { BehaviorSubject, EMPTY, Observable } from 'rxjs';
import { catchError, tap } from 'rxjs/operators';
import { HttpErrorResponse } from '@angular/common/http';
import { DataApiService } from '../../../services/data-api.service';
import { MensajesHttpService } from '../../../utils/mensajesHttp/mensajes-http.service';


@Injectable({
  providedIn: 'root',
})
export class EstadoRevendedorasFacadeService {

  private dataApi = inject(DataApiService);
  private _mensajesHttp = inject(MensajesHttpService);

  private Cargando$ = new BehaviorSubject<boolean>(false);
  public responseCargando$: Observable<boolean> = this.Cargando$.asObservable();

  private Estado$ = new BehaviorSubject<any[]>([]);
  public responseEstado$: Observable<any[]> = this.Estado$.asObservable();

  private Detalle$ = new BehaviorSubject<any[]>([]);
  public responseDetalle$: Observable<any[]> = this.Detalle$.asObservable();

  private seg(valor: any, centinela: any = 0): string {
    if (valor === null || valor === undefined || valor === '') { return String(centinela); }
    return encodeURIComponent(String(valor));
  }


  MostrarEstado(busqueda: string) {
    const url = `inventario/v1/estado-revendedoras/${this.seg(busqueda, 'null')}`;

    this.Cargando$.next(true);
    this.Estado$.next([]);
    const request$ = this.dataApi.GetDataApi(url, '').pipe(
      tap((result: any) => {
        this.Cargando$.next(false);
        this.Estado$.next(result.data.Table0);
      }),
      catchError((error: HttpErrorResponse) => {
        this.Cargando$.next(false);
        this.Estado$.next([]);
        this._mensajesHttp.mostrarErrorHttp(error, 'Ocurrio un error al mostrar el estado por revendedora', '');
        return EMPTY;
      })
    );
    return request$.subscribe();
  }


  MostrarDetalle(idAlmacen: number) {
    const url = `inventario/v1/estado-revendedora/detalle/${this.seg(idAlmacen)}`;

    const request$ = this.dataApi.GetDataApi(url, '').pipe(
      tap((result: any) => { this.Detalle$.next(result.data.Table0); }),
      catchError((error: HttpErrorResponse) => {
        this.Detalle$.next([]);
        this._mensajesHttp.mostrarErrorHttp(error, 'Ocurrio un error al mostrar el detalle', '');
        return EMPTY;
      })
    );
    return request$.subscribe();
  }
}
