import { Component, inject, TemplateRef } from '@angular/core';
import { EstadoRevendedorasFacadeService } from './estado-revendedoras-facade.service';
import { MatDialog } from '@angular/material/dialog';
import { FormControl } from '@angular/forms';
import { debounceTime, distinctUntilChanged } from 'rxjs/operators';

@Component({
  selector: 'app-estado-revendedoras',
  templateUrl: './estado-revendedoras.component.html',
  styleUrl: './estado-revendedoras.component.scss',
  standalone: false
})
export class EstadoRevendedorasComponent {
  public estadoFacade = inject(EstadoRevendedorasFacadeService);
  private dialog = inject(MatDialog);

  public buscar = new FormControl('');
  public revendedoraSeleccionada: any = null;

  ngOnInit(): void {
    this.cargar();
    this.buscar.valueChanges
      .pipe(debounceTime(350), distinctUntilChanged())
      .subscribe(() => this.cargar());
  }

  private cargar() {
    const texto = this.buscar.value && this.buscar.value.trim() !== '' ? this.buscar.value : 'null';
    this.estadoFacade.MostrarEstado(texto);
  }

  verDetalle(item: any, modal: TemplateRef<any>) {
    this.revendedoraSeleccionada = item;
    this.estadoFacade.MostrarDetalle(item.id_almacen);
    this.dialog.open(modal, { panelClass: 'app-full-bleed-dialog' });
  }
}
