import { NgModule } from '@angular/core';
import { RouterModule, Routes } from '@angular/router';
import { EntregasComponent } from './entregas/entregas.component';
import { LiquidacionesComponent } from './liquidaciones/liquidaciones.component';
import { DevolucionesComponent } from './devoluciones/devoluciones.component';
import { EstadoRevendedorasComponent } from './estado-revendedoras/estado-revendedoras.component';

const routes: Routes = [
  {
    path: 'entregas',
    component: EntregasComponent
  },
  {
    path: 'liquidacion',
    component: LiquidacionesComponent
  },
  {
    path: 'devoluciones',
    component: DevolucionesComponent
  },
  {
    path: 'revendedoras/estado',
    component: EstadoRevendedorasComponent
  }
];

@NgModule({
  imports: [RouterModule.forChild(routes)],
  exports: [RouterModule]
})
export class ConsignacionoutingModule { }
