import { Component, inject, TemplateRef } from '@angular/core';
import { AlmacenesFacadeService } from '../../inventario/almacenes/almacenes-facade.service';
import { ProductosFacadeService } from '../../inventario/productos/productos-facade.service';
import { LiquidacionesFacadeService } from './liquidaciones-facade.service';
import { ToastrServiceLocal } from '../../../services/toast/toastr.service';
import { FormArray, FormBuilder, FormControl, FormGroup, Validators } from '@angular/forms';
import { MatDialog } from '@angular/material/dialog';

export interface BusquedaProductos {
  busqueda: string | null;
  idMarca: string | null;
  idCategoria: string | null;
  idSubCategoria: string | null;
  activo: string | null;
  perecedero: string | null;
  requiereLote: string | null;
  bajoStock: number | null;
  pagina: number;
  tamanoPagina: number;
}

@Component({
  selector: 'app-liquidaciones',
  templateUrl: './liquidaciones.component.html',
  styleUrl: './liquidaciones.component.scss',
  standalone: false
})
export class LiquidacionesComponent {

  public almacenFacade = inject(AlmacenesFacadeService);
  public productosFacade = inject(ProductosFacadeService);
  public liquidacionesFacade = inject(LiquidacionesFacadeService);
  public toastFacade = inject(ToastrServiceLocal);
  private dialog = inject(MatDialog);

  public formLiq: FormGroup;
  public guardando = false;
  public usuarioActual: any;
  public liquidacionSeleccionada: any = null;

  private almacenes: any[] = [];
  private idRevendedora: number | null = null;
  public idAlmacenRevendedora: number | null = null;
  
  public formIdRevendedorasBusqueda = new FormControl('');

  constructor(private fb: FormBuilder) {
    this.formLiq = this.fb.group({
      idAlmacenRevendedora: [null, Validators.required],
      lineas: this.fb.array([])
    });
  }

  ngOnInit(): void {
    this.almacenFacade.MostrarAlmacenes("0");
    this.almacenFacade.responseAlmacenes$.subscribe(a => this.almacenes = a ?? []);
    this.cargarHistorial();

    this.formIdRevendedorasBusqueda.valueChanges.subscribe(() => this.filtrarBusquedaLiquidaciones());
  }

  get lineas(): FormArray {
    return this.formLiq.get('lineas') as FormArray;
  }

  private cargarHistorial() {
    this.liquidacionesFacade.MostrarLiquidaciones({
      idRevendedora: 0,
      estado: 'null',
      pagina: 1,
      tamanoPagina: 100
    });
  }

  private filtrarBusquedaLiquidaciones(){
     this.liquidacionesFacade.MostrarLiquidaciones({
      idRevendedora: this.formIdRevendedorasBusqueda.value,
      estado: 'null',
      pagina: 1,
      tamanoPagina: 100
    });
  }

  onRevendedora(idAlmacen: number) {
    const alm = this.almacenes.find(a => a.id === idAlmacen);
    this.idRevendedora = alm?.id_revendedora ?? null;
    this.idAlmacenRevendedora = idAlmacen;
    this.liquidacionesFacade.MostrarProductosConsigna(this.idAlmacenRevendedora, '');
    this.lineas.clear();
  }

  agregarLinea() {
    if (this.idAlmacenRevendedora === null) {
      this.toastFacade.mensajeError("Primero selecciona la revendedora", "");
      return;
    }
    this.lineas.push(this.fb.group({
      idProducto: [null, Validators.required],
      productoNombre: [''],
      stockDisponible: [0],
      cantidadVendida: [null, [Validators.required, Validators.min(0.0001)]],
      precioConsigna: [null, [Validators.required, Validators.min(0)]],
      precioVentaPublico: [null, [Validators.min(0)]]
    }));
  }

  eliminarLinea(i: number) {
    this.lineas.removeAt(i);
  }

  buscarProducto(event: any) {
    if (this.idAlmacenRevendedora === null) {
      this.toastFacade.mensajeError("Primero selecciona la revendedora", "");
      return;
    }
    const texto = event.target.value;
    const busqueda = texto && texto.trim() !== '' ? texto : 'null';
    this.liquidacionesFacade.MostrarProductosConsigna(this.idAlmacenRevendedora, busqueda);
  }

  selectProducto(producto: any, i: number) {
    const linea = this.lineas.at(i);
    linea.patchValue({
      idProducto: producto.id,
      productoNombre: `${producto.sku} - ${producto.nombre}`,
      precioConsigna: producto.precio_venta ?? null, 
      stockDisponible: producto.stock_disponible ?? 0 
    });
  }

  subtotalLinea(i: number): number {
    const l = this.lineas.at(i);
    const cant = +l.get('cantidadVendida')?.value || 0;
    const precio = +l.get('precioConsigna')?.value || 0;
    return cant * precio;   
  }

  totalLiquidacion(): number {
    return this.lineas.controls.reduce((acc, l) => {
      const cant = +l.get('cantidadVendida')?.value || 0;
      const precio = +l.get('precioConsigna')?.value || 0;
      return acc + (cant * precio);
    }, 0);
  }

  limpiar() {
    this.lineas.clear();
    this.formLiq.reset();
    this.idRevendedora = null;
  }

  Guardar() {
    if (this.formLiq.invalid || this.lineas.length === 0) {
      this.formLiq.markAllAsTouched();
      return;
    }

    if (this.idRevendedora === null) {
      this.toastFacade.mensajeError("No se pudo determinar la revendedora del almacén seleccionado", "");
      return;
    }

    for (let i = 0; i < this.lineas.length; i++) {
      const l = this.lineas.at(i);
      const vendida = +l.get('cantidadVendida')?.value || 0;
      const disponible = +l.get('stockDisponible')?.value || 0;
      if (vendida > disponible) {
        this.toastFacade.mensajeError(
          `La línea ${i + 1} vende ${vendida} pero solo hay ${disponible} en consigna`, "");
        return;
      }
    }

    this.guardando = true;

    const datos = {
      idRevendedora: this.idRevendedora,
      idAlmacenRevendedora: this.formLiq.get('idAlmacenRevendedora')?.value,
      usuario: this.usuarioActual
    };

    const lineas = this.lineas.controls.map(l => ({
      idProducto: l.get('idProducto')?.value,
      cantidadVendida: +l.get('cantidadVendida')?.value,
      precioConsigna: +l.get('precioConsigna')?.value,
      precioVentaPublico: l.get('precioVentaPublico')?.value != null
        ? +l.get('precioVentaPublico')?.value : null
    }));


    this.liquidacionesFacade.RegistrarLiquidacion(datos, lineas, (ok: boolean) => {
      this.guardando = false;
      if (ok) {
        this.toastFacade.mensajeSuccess("Liquidación registrada con éxito", "");
        this.limpiar();
        this.cargarHistorial();
      }
    });
  }

  verDetalle(item: any, modal: TemplateRef<any>) {
    this.liquidacionSeleccionada = item;
    this.liquidacionesFacade.MostrarDetalle(item.id);
    this.dialog.open(modal, { panelClass: 'app-full-bleed-dialog' });
  }

}
