import { Component, inject } from '@angular/core';
import { EntregasFacadeService } from './entregas-facade.service';
import { ToastrServiceLocal } from '../../../services/toast/toastr.service';
import { FormBuilder, FormControl, FormGroup, Validators } from '@angular/forms';
import { AlmacenesFacadeService } from '../../inventario/almacenes/almacenes-facade.service';
import { ProductosFacadeService } from '../../inventario/productos/productos-facade.service';
import { LotesFacadeService } from '../../inventario/lotes/lotes-facade.service';
import { debounceTime, distinctUntilChanged } from 'rxjs/operators';

export interface BusquedaProductos {
  busqueda: string | null;
  idMarca: string | null;
  idCategoria: string | null;
  idSubCategoria: string | null;
  activo: string | null;
  perecedero: string | null;
  requiereLote: string | null;
  bajoStock: number | null;
  pagina: number;
  tamanoPagina: number;
}

@Component({
  selector: 'app-entregas',
  templateUrl: './entregas.component.html',
  styleUrl: './entregas.component.scss',
  standalone: false
})
export class EntregasComponent {

  public almacenFacade = inject(AlmacenesFacadeService);
  public productosFacade = inject(ProductosFacadeService);
  public lotesFacade = inject(LotesFacadeService);
  public entregasFacade = inject(EntregasFacadeService);
  public toastFacade = inject(ToastrServiceLocal);

  public formEntrega: FormGroup;
  public productoNombre = '';
  public requiereLote = false;
  public lotes: any[] = [];
  public guardando = false;
  public usuarioActual: any;
  public formRevendedoras = new FormControl('');

  public buscar = new FormControl('');

  constructor(private fb: FormBuilder) {
    this.almacenFacade.MostrarAlmacenes('0');
    this.almacenFacade.MostrarRevendedoras('0');
    
    this.formEntrega = this.fb.group({
      idAlmacenDestino: [null, Validators.required],   
      idAlmacenOrigen: [null, Validators.required], 
      idProducto: [null, Validators.required],
      idLote: [null],
      cantidad: [null, [Validators.required, Validators.min(0.0001)]]
    });
  }

  ngOnInit(): void {
    this.cargarEntregas();

    this.buscar.valueChanges
      .pipe(debounceTime(350), distinctUntilChanged())
      .subscribe(() => this.cargarEntregas());

    this.formRevendedoras.valueChanges.subscribe(() => this.filtrarRevendedoraBusqueda());
  }

  private cargarEntregas() {
    const texto = this.buscar.value && this.buscar.value.trim() !== '' ? this.buscar.value : 'null';

    this.entregasFacade.MostrarEntregasConsigna({
      idRevendedora: 0,
      busqueda: texto,
      pagina: 1,
      tamanoPagina: 100
    });
  }

  private filtrarRevendedoraBusqueda(){
    this.entregasFacade.MostrarEntregasConsigna({
      idRevendedora: this.formRevendedoras.value,
      busqueda: '',
      pagina: 1,
      tamanoPagina: 100
    });
  }

  onRevendedora() {
  }

  buscarProducto(event: any) {
    const texto = event.target.value;
    this.productosFacade.MostrarProductos(this.filtroBusqueda(texto));
  }

  private filtroBusqueda(texto: string): BusquedaProductos {
    return {
      busqueda: texto && texto.trim() !== '' ? texto : null,
      idMarca: null,
      idCategoria: null,
      idSubCategoria: null,
      activo: '1',
      perecedero: null,
      requiereLote: null,
      bajoStock: null,
      pagina: 1,
      tamanoPagina: 20
    };
  }

  selectProducto(producto: any) {
    this.productoNombre = `${producto.sku} - ${producto.nombre}`;
    this.requiereLote = producto.requiere_lote === 1 || producto.requiere_lote === true;

    this.formEntrega.patchValue({
      idProducto: producto.id,
      idLote: null
    });

    if (this.requiereLote) {
      this.lotesFacade.MostrarLotesProducto(producto.id, (lotes: any[]) => {
        this.lotes = lotes ?? [];
      });
    } else {
      this.lotes = [];
    }
  }

  limpiar() {
    this.formEntrega.reset();
    this.productoNombre = '';
    this.requiereLote = false;
    this.lotes = [];
  }

  Guardar() {
    if (this.formEntrega.invalid) {
      this.formEntrega.markAllAsTouched();
      if (this.requiereLote && !this.formEntrega.get('idLote')?.value) {
        this.toastFacade.mensajeError("Es requerido seleccionar el lote", "");
      }
      return;
    }

    if (this.formEntrega.get('idAlmacenOrigen')?.value === this.formEntrega.get('idAlmacenDestino')?.value) {
      this.toastFacade.mensajeError("El origen y el destino no pueden ser el mismo almacén", "");
      return;
    }

    this.guardando = true;

    const payload = {
      idProducto: this.formEntrega.get('idProducto')?.value,
      idAlmacenOrigen: this.formEntrega.get('idAlmacenOrigen')?.value,
      idAlmacenDestino: this.formEntrega.get('idAlmacenDestino')?.value,
      idLote: this.formEntrega.get('idLote')?.value ?? null,
      cantidad: +this.formEntrega.get('cantidad')?.value,
      usuario: this.usuarioActual
    };

    this.entregasFacade.EntregasConsigna(payload, (ok: boolean) => {
      this.guardando = false;
      if (ok) {
        this.toastFacade.mensajeSuccess("Entrega en consigna registrada con éxito", "");
        this.limpiar();
        this.cargarEntregas();   
      }
    });
  }



}
